      ],
      "fix_pushed": true,
      "settled_by_id": "c:5670249276",
      "settled_by_quote": "I replaced the if(EXISTS) checks with explicit HAS_BASH_COMPLETION and HAS_FISH_COMPLETION keywords."
    },
    {
      "id": "c:4030028919",
      "kind": "approach",
      "harm": "Build options for completions don't affect build and 1:1 target-to-component relationship is inflexible; wrapper install_binary_component attracts responsibilities",
